"""LLM access for Pitstop: the hackathon LiteLLM proxy, traced through neatlogs."""

from __future__ import annotations

import json
import os
import re
from dataclasses import dataclass, field

LITELLM_BASE_URL = "https://litellm.vision.aivar.app/v1"

# USD per 1M tokens (input, output). Estimates for budgeting, not invoices.
PRICES = {
    "nova-micro": (0.035, 0.14),
    "nova-lite": (0.06, 0.24),
    "nova-pro": (0.8, 3.2),
    "nova-2-lite": (0.33, 2.75),
    "claude-haiku": (1.0, 5.0),
    "claude-sonnet-4.6": (3.0, 15.0),
    "claude-opus-4.6": (5.0, 25.0),
}


def cost_usd(model: str, prompt_tokens: int, completion_tokens: int) -> float:
    pin, pout = PRICES.get(model, (3.0, 15.0))
    return (prompt_tokens * pin + completion_tokens * pout) / 1_000_000


class BudgetExceeded(RuntimeError):
    pass


def parse_json(text: str):
    """Pull the first JSON object or array out of a model reply."""
    text = (text or "").strip()
    fenced = re.search(r"```(?:json)?\s*(.*?)```", text, re.S)
    if fenced:
        text = fenced.group(1).strip()
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        pass
    starts = [i for i in (text.find("{"), text.find("[")) if i >= 0]
    if not starts:
        raise ValueError(f"no JSON in model reply: {text[:200]!r}")
    start = min(starts)
    closer = "}" if text[start] == "{" else "]"
    end = text.rfind(closer)
    return json.loads(text[start : end + 1])


@dataclass
class Ledger:
    """Tracks what Pitstop itself spends so a run can't drain the team budget."""

    budget_usd: float
    spent_usd: float = 0.0
    calls: int = 0
    tokens: int = 0
    entries: list = field(default_factory=list)

    def charge(self, label: str, usd: float, tokens: int = 0) -> None:
        self.spent_usd += usd
        self.tokens += tokens
        self.calls += 1
        self.entries.append({"label": label, "usd": round(usd, 6), "tokens": tokens})

    def check(self) -> None:
        if self.spent_usd >= self.budget_usd:
            raise BudgetExceeded(f"spent ${self.spent_usd:.4f} of ${self.budget_usd:.2f} budget")


class LLM:
    def __init__(self, model: str, ledger: Ledger, client=None) -> None:
        self.model = model
        self.ledger = ledger
        if client is None:
            import neatlogs
            from openai import OpenAI

            client = neatlogs.wrap(
                OpenAI(
                    base_url=os.environ.get("LLM_BASE_URL", LITELLM_BASE_URL),
                    api_key=os.environ["LITELLM_API_KEY"],
                    max_retries=3,
                    timeout=180,
                )
            )
        self.client = client

    def json(self, label: str, system: str, user: str, max_tokens: int = 4000):
        """Ask for a JSON reply. Retries once with the parse error if the reply isn't JSON."""
        messages = [{"role": "system", "content": system}, {"role": "user", "content": user}]
        for attempt in range(2):
            self.ledger.check()
            response = self.client.chat.completions.create(
                model=self.model, messages=messages, temperature=0, max_tokens=max_tokens
            )
            usage = getattr(response, "usage", None)
            pt = getattr(usage, "prompt_tokens", 0) or 0
            ct = getattr(usage, "completion_tokens", 0) or 0
            self.ledger.charge(label, cost_usd(self.model, pt, ct), pt + ct)
            text = response.choices[0].message.content or ""
            try:
                return parse_json(text)
            except (ValueError, json.JSONDecodeError) as exc:
                if attempt:
                    raise
                messages += [
                    {"role": "assistant", "content": text},
                    {"role": "user", "content": f"That was not valid JSON ({exc}). Reply with only the JSON."},
                ]

"""The agent repo Pitstop works on: config, eval/test runs, edits and git."""

from __future__ import annotations

import fnmatch
import json
import os
import pathlib
import py_compile
import subprocess
import sys
import tomllib
from dataclasses import dataclass


@dataclass
class Edit:
    file: str
    search: str
    replace: str


class EditError(ValueError):
    pass


class Target:
    def __init__(self, root: str | os.PathLike, model: str, python: str | None = None) -> None:
        self.root = pathlib.Path(root).resolve()
        config = tomllib.loads((self.root / "pitstop.toml").read_text(encoding="utf-8"))["target"]
        self.name = config["name"]
        self.description = config.get("description", "")
        self.eval_cmd = config["eval_cmd"]
        self.test_cmd = config.get("test_cmd")
        self.editable = config["editable"]
        self.context = config.get("context", [])
        self.model = model
        self.python = python or sys.executable
        self.work = self.root / ".pitstop"
        self.work.mkdir(exist_ok=True)

    # -- commands ---------------------------------------------------------
    def _expand(self, cmd: list[str], **extra) -> list[str]:
        values = {"python": self.python, "model": self.model, **extra}
        return [part.format(**values) for part in cmd]

    def _run(self, cmd: list[str], env: dict | None = None, timeout: int = 1800) -> subprocess.CompletedProcess:
        return subprocess.run(
            cmd, cwd=self.root, env={**os.environ, **(env or {})}, capture_output=True,
            text=True, encoding="utf-8", errors="replace", timeout=timeout,
        )

    def evaluate(self, run_id: str, variant: str) -> dict:
        out = self.work / "runs" / run_id / f"{variant}.json"
        out.parent.mkdir(parents=True, exist_ok=True)
        proc = self._run(
            self._expand(self.eval_cmd, out=str(out)),
            env={"PITSTOP_RUN_ID": run_id, "PITSTOP_VARIANT": variant, "PYTHONIOENCODING": "utf-8"},
        )
        if proc.returncode != 0 or not out.exists():
            raise RuntimeError(f"eval command failed ({proc.returncode}):\n{proc.stderr[-3000:]}")
        results = json.loads(out.read_text(encoding="utf-8"))
        results["path"] = str(out)
        return results

    def run_tests(self) -> tuple[bool, str]:
        if not self.test_cmd:
            return True, "no test command configured"
        proc = self._run(self._expand(self.test_cmd), timeout=600)
        return proc.returncode == 0, (proc.stdout + proc.stderr)[-4000:]

    # -- files ------------------------------------------------------------
    def is_editable(self, rel: str) -> bool:
        rel = rel.replace("\\", "/")
        return any(fnmatch.fnmatch(rel, pattern) for pattern in self.editable)

    def read(self, rel: str) -> str:
        return (self.root / rel).read_text(encoding="utf-8")

    def source_bundle(self, include_context: bool = True) -> str:
        files = list(self.editable) + (list(self.context) if include_context else [])
        parts = []
        for rel in files:
            path = self.root / rel
            if path.exists():
                tag = "EDITABLE" if self.is_editable(rel) else "READ-ONLY"
                parts.append(f"### {rel} ({tag})\n```\n{path.read_text(encoding='utf-8')}\n```")
        return "\n\n".join(parts)

    def apply(self, edits: list[Edit]) -> list[str]:
        """Apply search/replace edits atomically. Raises EditError and leaves files untouched on any problem."""
        staged: dict[str, str] = {}
        for edit in edits:
            rel = edit.file.replace("\\", "/")
            if not self.is_editable(rel):
                raise EditError(f"{rel} is not editable (allowed: {', '.join(self.editable)})")
            text = staged.get(rel, self.read(rel))
            count = text.count(edit.search)
            if count != 1:
                raise EditError(
                    f"search block for {rel} matched {count} times; it must match exactly once. "
                    f"Block was:\n{edit.search[:500]}"
                )
            staged[rel] = text.replace(edit.search, edit.replace, 1)
        backups = {rel: self.read(rel) for rel in staged}
        for rel, text in staged.items():
            (self.root / rel).write_text(text, encoding="utf-8")
        try:
            for rel in staged:
                if rel.endswith(".py"):
                    py_compile.compile(str(self.root / rel), doraise=True)
        except py_compile.PyCompileError as exc:
            for rel, text in backups.items():
                (self.root / rel).write_text(text, encoding="utf-8")
            raise EditError(f"edit produced invalid Python: {exc.msg}") from exc
        return sorted(staged)

    # -- git --------------------------------------------------------------
    def git(self, *args: str) -> str:
        proc = self._run(["git", *args], timeout=120)
        if proc.returncode != 0:
            raise RuntimeError(f"git {' '.join(args)} failed: {proc.stderr.strip()}")
        return proc.stdout.strip()

    def ensure_clean(self) -> None:
        dirty = [line for line in self.git("status", "--porcelain").splitlines() if ".pitstop" not in line]
        if dirty:
            raise RuntimeError(f"target has uncommitted changes:\n" + "\n".join(dirty))

    def start_branch(self, run_id: str) -> str:
        branch = f"pitstop/{run_id}"
        self.git("checkout", "-b", branch)
        return branch

    def diff(self) -> str:
        return self.git("diff")

    def revert(self) -> None:
        self.git("checkout", "--", *self.editable_existing())

    def editable_existing(self) -> list[str]:
        return [rel for rel in self.editable if (self.root / rel).exists()]

    def commit(self, message: str) -> str:
        self.git("add", *self.editable_existing())
        self.git("commit", "-q", "-m", message)
        return self.git("rev-parse", "HEAD")

"""Turn eval results and neatlogs traces into compact evidence a model can reason over."""

from __future__ import annotations

import json
import os
import shutil
import subprocess

MAX_TASKS = 4


def _step_line(step: dict) -> str:
    parts = [f"step {step['step']}: prompt={step['prompt_tokens']}tok completion={step['completion_tokens']}tok"]
    for r in step.get("tool_results_in", []):
        flag = " ERROR" if r["error"] else ""
        parts.append(f"  <- {r['tool']}({r['args']}) returned {r['chars']} chars{flag}: {r['excerpt'][:160]!r}")
    for c in step.get("tool_calls_out", []):
        parts.append(f"  -> calls {c['tool']}({c['args']})")
    if step.get("content_excerpt"):
        parts.append(f"  -> answers: {step['content_excerpt'][:240]!r}")
    return "\n".join(parts)


def task_digest(task: dict, trace_summary: str | None = None) -> str:
    lines = [
        f"## task `{task['id']}` input={task['input']!r} passed={task['passed']}",
        f"checks: {json.dumps(task['checks'])}",
        f"tokens={task['total_tokens']} steps={task['n_steps']} tool_errors={task['tool_errors']} latency={task['latency_s']}s",
    ]
    if task.get("failures"):
        lines.append("failures:\n" + "\n".join(f"- {f}" for f in task["failures"]))
    if task.get("error"):
        lines.append(f"exception: {task['error']}")
    lines.append("timeline:\n" + "\n".join(_step_line(s) for s in task.get("steps", [])))
    if trace_summary:
        lines.append(f"neatlogs trace {task.get('trace_id')}:\n{trace_summary}")
    return "\n".join(lines)


def build(results: dict, traces: "NeatlogsTraces | None" = None) -> str:
    """Evidence for the failing tasks (worst first), plus the run summary."""
    tasks = sorted(results["tasks"], key=lambda t: (t["passed"], -len(t["failures"]), -t["total_tokens"]))
    failing = [t for t in tasks if not t["passed"]][:MAX_TASKS]
    chunks = [f"# eval summary\n{json.dumps(results['summary'])}"]
    for task in failing:
        summary = traces.summarize(task.get("trace_id")) if traces else None
        chunks.append(task_digest(task, summary))
    passing = [t["id"] for t in tasks if t["passed"]]
    if passing:
        chunks.append(f"passing tasks (do not regress these): {passing}")
    return "\n\n".join(chunks)


class NeatlogsTraces:
    """Reads traces back from neatlogs with the `neatlogs` CLI (OAuth login required).

    Enabled when the CLI is on PATH and NEATLOGS_CLI_PROJECT is set. Every call is
    best-effort: Pitstop falls back to its own run telemetry if a read fails.
    """

    def __init__(self, project: str | None = None, host: str | None = None) -> None:
        self.project = project or os.environ.get("NEATLOGS_CLI_PROJECT")
        self.host = host or os.environ.get("NEATLOGS_CLI_HOST")
        self.exe = shutil.which("neatlogs")
        self.reads = 0
        self.failures: list[str] = []

    @property
    def enabled(self) -> bool:
        return bool(self.exe and self.project)

    def _cli(self, *args: str):
        cmd = [self.exe]
        if self.host:
            cmd += ["--host", self.host]
        cmd += ["--project", self.project, *args, "--json"]
        proc = subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=60)
        if proc.returncode != 0:
            raise RuntimeError(proc.stderr.strip()[:300] or f"exit {proc.returncode}")
        return json.loads(proc.stdout)

    def spans(self, trace_id: str) -> list[dict]:
        data = self._cli("traces", "spans", "list", trace_id, "--limit", "100")
        self.reads += 1
        if isinstance(data, dict):
            for key in ("spans", "items", "data", "results"):
                if isinstance(data.get(key), list):
                    return data[key]
        return data if isinstance(data, list) else []

    def summarize(self, trace_id: str | None) -> str | None:
        if not (self.enabled and trace_id):
            return None
        try:
            spans = self.spans(trace_id)
        except Exception as exc:
            self.failures.append(f"{trace_id}: {exc}")
            return None
        lines = []
        for span in spans[:60]:
            name = _pick(span, "name", "span_name", "spanName") or "?"
            kind = _pick(span, "kind", "span_kind", "spanKind", "type") or ""
            status = _pick(span, "status", "status_code", "statusCode") or ""
            dur = _pick(span, "duration_ms", "durationMs", "latency_ms", "duration")
            tokens = _pick(span, "total_tokens", "totalTokens", "tokens")
            err = _pick(span, "error", "error_message", "exception", "status_message")
            bits = [f"{kind} {name}".strip(), f"status={status}" if status else "", f"dur={dur}" if dur else "",
                    f"tokens={tokens}" if tokens else "", f"error={str(err)[:160]}" if err else ""]
            lines.append("- " + " ".join(b for b in bits if b))
        return "\n".join(lines) or None


def _pick(d: dict, *keys):
    for key in keys:
        if key in d and d[key] not in (None, "", {}):
            value = d[key]
            return value if not isinstance(value, dict) else json.dumps(value)[:120]
        attrs = d.get("attributes") or {}
        if key in attrs and attrs[key] not in (None, ""):
            return attrs[key]
    return None

